module devmcp

fn config_edit_tool_specs(revision string) []ToolSpec {
	target := revision + ',"target_id":{"type":"string"}'
	mut specs := [
		ToolSpec{name: 'shared_config_get', description: 'Discover safe shared configuration components, actual relative sources and scalar/array field paths in the bound local or registered remote environment. Does not expose raw TOML, private values, app sources or control identity. Read effective runtime schema separately. Requires running effective configuration.', properties: target, required: '"binding_revision"', read_only: true},
		ToolSpec{name: 'shared_config_edit_prepare', description: 'Preview up to 32 typed field edits across existing shared components and include files. Each edit selects domain, component and field path segments; value sets scalar/array, remove deletes the assignment. resources/policies component uses category/id, pipelines uses stable pipeline ID, server/observability uses empty component. No raw source paths/TOML, credentials, executable/storage paths or app component edits. Preserve unrelated bytes and validate entire environment. Retains the effective baseline in private persistent history. Requires separate preflight.', properties: target + ',"edits":{"type":"array","minItems":1,"maxItems":32,"items":{"type":"object","additionalProperties":false,"properties":{"domain":{"type":"string","enum":["listeners","resources","engines","adapters","transforms","policies","providers","pipelines","server","observability"]},"component":{"type":"string"},"field":{"type":"array","minItems":1,"maxItems":5,"items":{"type":"string"}},"value":{},"remove":{"type":"boolean"}},"required":["domain","field"]}}', required: '"binding_revision","edits"'},
		ToolSpec{name: 'config_history_list', description: 'List private persisted configuration history for this selected local/remote environment without raw configuration or credentials. Local history also includes existing Desktop GUI versions, not just MCP-created versions. Works while runtime is stopped; remote target host must be connected. History is stored on this Desktop, max 20 snapshots per environment.', properties: target, required: '"binding_revision"', read_only: true},
		ToolSpec{name: 'config_history_capture', description: 'Persist the currently ready effective configuration as a private history version, including manually edited configurations. Does not publish or restart. Returns version_id; repeated same source revision is deduplicated. Requires a running effective environment.', properties: target, required: '"binding_revision"'},
		ToolSpec{name: 'config_history_restore_prepare', description: 'Prepare restoration of an exact persisted version_id, including local Desktop GUI history. Independent of old edit plan/session. Checks selected target, current boot/full revision, source membership and whole configuration. Protects control identity, app configuration and include topology. Runtime must be running and effective; missing/renamed sources require Desktop recovery.', properties: target + ',"version_id":{"type":"string"}', required: '"binding_revision","version_id"'},
		ToolSpec{name: 'shared_config_operation_get', description: 'Poll asynchronous shared-edit/history operations after accepted response; operation records are scoped to this binding and Desktop session. Failed/uncertain writes require live state inspection before retry.', properties: revision + ',"operation_id":{"type":"string"}', required: '"binding_revision","operation_id"', read_only: true},
	]
	for name in ['shared_config_edit_preflight', 'config_history_restore_preflight'] {
		specs << ToolSpec{name: name, description: 'Validate the exact shared configuration/history plan through runtime Admin; check full source revision and boot identity before enabling apply. Does not publish or restart.', properties: target + ',"plan_id":{"type":"string"}', required: '"binding_revision","plan_id"'}
	}
	for name in ['shared_config_edit_apply', 'shared_config_edit_restore', 'config_history_restore_apply', 'config_history_restore_undo'] {
		specs << ToolSpec{name: name, description: 'After Desktop review, execute this exact preflighted configuration/history plan. Returns accepted operation_id; poll shared_config_operation_get then verify real business requests. Restarts the entire existing environment. Restore/undo replays exact baseline only while full current revision matches; supports stopped managed runtime recovery. Old plans expire; retained version_id can prepare a fresh restore in a later Desktop session.', properties: target + ',"plan_id":{"type":"string"}', required: '"binding_revision","plan_id"'}
	}
	return specs
}

fn is_config_edit_tool(name string) bool {
	return name in ['shared_config_get', 'shared_config_edit_prepare', 'shared_config_edit_preflight', 'shared_config_edit_apply', 'shared_config_edit_restore', 'config_history_list', 'config_history_capture', 'config_history_restore_prepare', 'config_history_restore_preflight', 'config_history_restore_apply', 'config_history_restore_undo', 'shared_config_operation_get']
}
